import type { Workbook } from '@univerjs/core';
import type { IDefinedNamesServiceParam } from '@univerjs/engine-formula';
import type { ISelectionWithStyle } from '@univerjs/sheets';
import {
    AbsoluteRefType,
    EDITOR_ACTIVATED,
    FOCUSING_EDITOR_BUT_HIDDEN,
    FOCUSING_EDITOR_INPUT_FORMULA,
    FOCUSING_EDITOR_STANDALONE,
    FOCUSING_FX_BAR_EDITOR,
    KeyCode,
    Tools,
} from '@univerjs/core';
import { isReferenceStringWithEffectiveColumn } from '@univerjs/engine-formula';
import { DeviceInputEventType, hasCJKText } from '@univerjs/engine-render';
import { SetCellEditVisibleOperation } from '../../commands/operations/cell-edit.operation';

interface IDefinedNameValidationDeps {
    unitId: string;
    name: string;
    workbook: Workbook;
    definedNamesService: { getValueByName: (unitId: string, name: string) => IDefinedNamesServiceParam | null };
    superTableService: { hasTable: (name: string) => boolean };
    functionService: { hasExecutor: (name: string) => boolean };
}

/**
 * Validates whether a given name is acceptable as a defined name in the workbook.
 * Returns an error message key (string) when the name is not acceptable, otherwise `null`.
 */
export function validateDefinedName(deps: IDefinedNameValidationDeps): string | null | undefined {
    const { unitId, name, workbook, definedNamesService, superTableService, functionService } = deps;

    if (!name || name.length === 0) {
        return 'definedName.nameEmpty';
    }

    // The defined name can't be duplicate with existing defined names.
    if (definedNamesService.getValueByName(unitId, name)) {
        return 'definedName.nameDuplicate';
    }

    // The defined name can't be duplicate with existing table names.
    if (superTableService.hasTable(name)) {
        return 'definedName.nameDuplicate';
    }

    // The defined name can't be a reference string with effective column, which will cause confusion.
    if (
        !Tools.isValidParameter(name) ||
        isReferenceStringWithEffectiveColumn(name) ||
        (!Tools.isStartValidPosition(name) && !hasCJKText(name.substring(0, 1)))
    ) {
        return 'definedName.nameInvalid';
    }

    // The defined name can't be duplicate with existing sheet names.
    const worksheets = workbook.getSheets();
    if (worksheets.some((sheet) => sheet.getName() === name)) {
        return 'definedName.nameSheetConflict';
    }

    // The defined name can't be duplicate with existing function names.
    if (functionService.hasExecutor(name.toUpperCase())) {
        return 'definedName.nameConflict';
    }

    return null;
}

export type IDefinedNameBoxAction =
    | { type: 'focusDefinedName'; definedName: IDefinedNamesServiceParam }
    | { type: 'focusSelection'; refString: string }
    | { type: 'createDefinedName'; name: string }
    | { type: 'reset' };

interface IResolveDefinedNameBoxActionDeps extends IDefinedNameValidationDeps {
    inputValue: string;
    rangeString: string;
}

/**
 * Determines the action to take when the user presses Enter in the defined-name input box.
 */
export function resolveDefinedNameBoxAction(deps: IResolveDefinedNameBoxActionDeps): IDefinedNameBoxAction {
    const { unitId, workbook, definedNamesService, superTableService, functionService, inputValue } = deps;

    // Case-insensitively matches an existing defined name.
    const definedName = definedNamesService.getValueByName(unitId, inputValue);
    if (definedName) {
        return { type: 'focusDefinedName', definedName };
    }

    // A valid cell or range reference string.
    if (isReferenceStringWithEffectiveColumn(inputValue)) {
        return { type: 'focusSelection', refString: inputValue };
    }

    // A valid new name with no conflicts.
    const validationResult = validateDefinedName({
        unitId,
        name: inputValue,
        workbook,
        definedNamesService,
        superTableService,
        functionService,
    });

    if (!validationResult) {
        return { type: 'createDefinedName', name: inputValue };
    }

    return { type: 'reset' };
}

/**
 * Builds an absolute reference string for the active sheet from the given selections.
 */
export function getAbsoluteRefStringFromSelection(
    workbook: Workbook,
    selections: ISelectionWithStyle[],
    refStringService: { convertRefersToAbsolute: (refString: string, rowAbsType: AbsoluteRefType, colAbsType: AbsoluteRefType, sheetName: string) => string }
): string {
    const worksheet = workbook.getActiveSheet();
    const sheetName = worksheet.getName();

    const { startRow, startColumn, endRow, endColumn } = selections[0].range;

    let refString: string;
    if (startRow === endRow && startColumn === endColumn) {
        refString = `${sheetName}!${Tools.chatAtABC(startColumn)}${startRow + 1}`;
    } else {
        refString = `${sheetName}!${Tools.chatAtABC(startColumn)}${startRow + 1}:${Tools.chatAtABC(endColumn)}${endRow + 1}`;
    }

    return refStringService.convertRefersToAbsolute(refString, AbsoluteRefType.ALL, AbsoluteRefType.ALL, sheetName);
}

interface IRestoreSheetNavigationDeps {
    unitId: string;
    input: { blur: () => void };
    commandService: { syncExecuteCommand: (id: string, params: object) => boolean };
    univerInstanceService: { focusUnit: (unitId: string) => void };
    editorService: { blur: (force?: boolean) => void; getEditor: () => { focus: () => void } | null | undefined };
    editorBridgeService: { isVisible: () => { visible: boolean }; getEditLocation: () => { unitId: string } | null };
    contextService: { setContextValue: (key: string, value: boolean) => void };
}

/**
 * Restores keyboard focus to the sheet grid after the user confirms a defined-name action.
 */
export function restoreSheetNavigationAfterDefinedNameConfirm(deps: IRestoreSheetNavigationDeps): boolean {
    const { unitId, input, commandService, univerInstanceService, editorService, editorBridgeService, contextService } = deps;

    input.blur();

    if (editorBridgeService.isVisible().visible) {
        commandService.syncExecuteCommand(SetCellEditVisibleOperation.id, {
            visible: false,
            eventType: DeviceInputEventType.Keyboard,
            keycode: KeyCode.ENTER,
            unitId: editorBridgeService.getEditLocation()!.unitId,
        });
    } else {
        editorService.blur(true);
        univerInstanceService.focusUnit(unitId);
        editorService.getEditor()?.focus();
        contextService.setContextValue(FOCUSING_EDITOR_INPUT_FORMULA, false);
        contextService.setContextValue(EDITOR_ACTIVATED, false);
        contextService.setContextValue(FOCUSING_EDITOR_BUT_HIDDEN, false);
        contextService.setContextValue(FOCUSING_EDITOR_STANDALONE, false);
        contextService.setContextValue(FOCUSING_FX_BAR_EDITOR, false);
    }

    return true;
}
